INSERT INTO hospital.panel_default_attributes
  (panel_id, panel_attribute_definition_id, default_value_text, source, sop_version)
SELECT p.id, pad.id, '1. Hospital emails cashless request + all docs to cashlesseverywhere@mediassist.in
2. Medi Assist contacts hospital → collects KYC + brief MoU
3. Evaluates hospital credentials
4. Creates provisional empanelment / hospital ID on insurer portal
5. Generates CCN (Claim Control Number)
6. Processes pre-auth → approval/denial/query to hospital + patient
7. Post-treatment: Hospital submits final docs within 15 days
8. Settlement within 30 days of complete docs', 'sop_seed', '2026-05'
FROM hospital.panels p, hospital.panel_attribute_definitions pad
WHERE p.code = 'MEDI_ASSIST' AND pad.key = 'sop_step_by_step'
ON CONFLICT (panel_id, panel_attribute_definition_id) DO NOTHING;
